def transform(grid):
    n, m = len(grid), len(grid[0])
    # Extend the diagonal color motif throughout the grid.
    diagonals = {}
    for r in range(n):
        for c in range(m):
            if grid[r][c]:
                diagonals.setdefault(c - r, grid[r][c])

    # The guide diagonals identify a repeating sequence of colors.
    keys = sorted(diagonals)
    colors = [diagonals[k] for k in keys]
    # Remove repeated colors while retaining their spatial order.
    seq = []
    for color in colors:
        if color not in seq:
            seq.append(color)

    # Align the sequence with the diagonal containing the first guide.
    base = keys[0]
    return [[seq[(c - r - base) % len(seq)] for c in range(m)]
            for r in range(n)]
